import * as cdk from 'aws-cdk-lib';
import * as route53 from 'aws-cdk-lib/aws-route53';
import type { Construct } from 'constructs';
import { DOMAIN_NAME } from './config.js';

/**
 * AWS's published Application Load Balancer canonical hosted zone ID, per region. Fixed
 * per-region constants AWS documents (https://docs.aws.amazon.com/general/latest/gr/elb.html),
 * not generated by this app -- needed because a Route53 ALIAS record to an ALB in a different
 * region than this stack can't reference a live CDK ALB construct (no native cross-region token
 * for that), so the alias target is built from plain strings instead.
 */
const ALB_HOSTED_ZONE_IDS: Record<string, string> = {
  'us-east-1': 'Z35SXDOTRQ7X7K',
  'us-east-2': 'Z3AADJGX6KTTL2',
  'us-west-2': 'Z1H1FL5HABSF5',
};

export interface DnsStackProps extends cdk.StackProps {
  /** DNS name of the currently-active region's ALB (ReconEphemeralStack's `AppUrl` output, minus
   *  the scheme). Optional: on the very first deploy, before any EphemeralStack exists, the zone
   *  is created with no record yet -- pass this (via `-c activeRegionAlbDnsName=...`) once the
   *  primary region's EphemeralStack is up, and again on every DR failover. */
  readonly activeRegionAlbDnsName?: string;
  /** AWS region code the ALB above lives in, used to resolve its canonical hosted zone id. */
  readonly activeRegion?: string;
}

/**
 * The one truly always-on stack: a public Route53 hosted zone for the app's domain, plus an apex
 * ALIAS record pointing at whichever region is currently serving traffic. Deliberately
 * region-agnostic and never destroyed -- it's what survives every DR failover, so the domain's
 * registrar NS delegation never has to change, only the record it resolves to.
 */
export class DnsStack extends cdk.Stack {
  readonly hostedZone: route53.PublicHostedZone;

  constructor(scope: Construct, id: string, props: DnsStackProps = {}) {
    super(scope, id, props);

    this.hostedZone = new route53.PublicHostedZone(this, 'Zone', {
      zoneName: DOMAIN_NAME,
    });

    if (props.activeRegionAlbDnsName && props.activeRegion) {
      const albHostedZoneId = ALB_HOSTED_ZONE_IDS[props.activeRegion];
      if (!albHostedZoneId) {
        throw new Error(`No known ALB hosted zone id for region ${props.activeRegion}`);
      }

      new route53.CfnRecordSet(this, 'ApexRecord', {
        hostedZoneId: this.hostedZone.hostedZoneId,
        // Trailing dot matches the canonical form CloudFormation/Route53 use for the zone's own
        // Name (PublicHostedZone appends it automatically) -- without it the record technically
        // still resolves, but diverges from the zone's own naming convention.
        name: `${DOMAIN_NAME}.`,
        type: 'A',
        aliasTarget: {
          dnsName: props.activeRegionAlbDnsName,
          hostedZoneId: albHostedZoneId,
          evaluateTargetHealth: false,
        },
      });
    }

    new cdk.CfnOutput(this, 'NameServers', {
      value: cdk.Fn.join(', ', this.hostedZone.hostedZoneNameServers ?? []),
      description: `Delegate ${DOMAIN_NAME} to these name servers at the domain registrar.`,
    });
  }
}
